#[derive(Debug, Clone, PartialEq, Eq)]
enum StructFieldValue {
    Scalar {
        value: i64,
        ty: CType,
        is_const: bool,
    },
    Array {
        value: Rc<RefCell<ArrayValue>>,
        is_const: bool,
    },
    Struct {
        type_name: String,
        fields: HashMap<String, StructFieldValue>,
        is_const: bool,
    },
    StructArray {
        type_name: String,
        elements: Vec<HashMap<String, StructFieldValue>>,
        is_const: bool,
    },
    Pointer {
        pointer: PointerValue,
        ty: PointeeType,
        is_const: bool,
        points_to_const: bool,
    },
}

impl StructFieldValue {
    fn is_const(&self) -> bool {
        match self {
            StructFieldValue::Scalar { is_const, .. }
            | StructFieldValue::Array { is_const, .. }
            | StructFieldValue::Struct { is_const, .. }
            | StructFieldValue::StructArray { is_const, .. }
            | StructFieldValue::Pointer { is_const, .. } => *is_const,
        }
    }

    fn contains_const(&self) -> bool {
        self.is_const()
            || match self {
                StructFieldValue::Struct { fields, .. } => {
                    fields.values().any(StructFieldValue::contains_const)
                }
                StructFieldValue::StructArray { elements, .. } => elements
                    .iter()
                    .any(|fields| fields.values().any(StructFieldValue::contains_const)),
                StructFieldValue::Scalar { .. }
                | StructFieldValue::Array { .. }
                | StructFieldValue::Pointer { .. } => false,
            }
    }

    fn mark_embedded_arrays_read_only(fields: &mut HashMap<String, StructFieldValue>) {
        for field in fields.values_mut() {
            match field {
                StructFieldValue::Array { value, .. } => value.borrow_mut().read_only = true,
                StructFieldValue::Struct { fields, .. } => {
                    Self::mark_embedded_arrays_read_only(fields)
                }
                StructFieldValue::StructArray { elements, .. } => {
                    for fields in elements {
                        Self::mark_embedded_arrays_read_only(fields);
                    }
                }
                StructFieldValue::Scalar { .. } | StructFieldValue::Pointer { .. } => {}
            }
        }
    }

    fn deep_clone(&self) -> Self {
        match self {
            StructFieldValue::Scalar {
                value,
                ty,
                is_const,
            } => StructFieldValue::Scalar {
                value: *value,
                ty: *ty,
                is_const: *is_const,
            },
            StructFieldValue::Array { value, is_const } => {
                let mut value = value.borrow().clone();
                value.read_only = *is_const;
                StructFieldValue::Array {
                    value: Rc::new(RefCell::new(value)),
                    is_const: *is_const,
                }
            }
            StructFieldValue::Struct {
                type_name,
                fields,
                is_const,
            } => {
                let mut fields = Self::deep_clone_fields(fields);
                if *is_const {
                    Self::mark_embedded_arrays_read_only(&mut fields);
                }
                StructFieldValue::Struct {
                    type_name: type_name.clone(),
                    fields,
                    is_const: *is_const,
                }
            }
            StructFieldValue::StructArray {
                type_name,
                elements,
                is_const,
            } => {
                let mut elements: Vec<_> = elements.iter().map(Self::deep_clone_fields).collect();
                if *is_const {
                    for fields in &mut elements {
                        Self::mark_embedded_arrays_read_only(fields);
                    }
                }
                StructFieldValue::StructArray {
                    type_name: type_name.clone(),
                    elements,
                    is_const: *is_const,
                }
            }
            StructFieldValue::Pointer {
                pointer,
                ty,
                is_const,
                points_to_const,
            } => StructFieldValue::Pointer {
                pointer: pointer.clone(),
                ty: ty.clone(),
                is_const: *is_const,
                points_to_const: *points_to_const,
            },
        }
    }

    fn deep_clone_fields(
        fields: &HashMap<String, StructFieldValue>,
    ) -> HashMap<String, StructFieldValue> {
        fields
            .iter()
            .map(|(name, value)| (name.clone(), value.deep_clone()))
            .collect()
    }

    fn copy_assign_from(&mut self, source: &StructFieldValue) -> CustResult<()> {
        match (self, source) {
            (
                StructFieldValue::Scalar { value, .. },
                StructFieldValue::Scalar {
                    value: source_value,
                    ..
                },
            ) => *value = *source_value,
            (
                StructFieldValue::Array { value, .. },
                StructFieldValue::Array {
                    value: source_value,
                    ..
                },
            ) => {
                value
                    .borrow_mut()
                    .elements
                    .clone_from(&source_value.borrow().elements);
            }
            (
                StructFieldValue::Struct { fields, .. },
                StructFieldValue::Struct {
                    fields: source_fields,
                    ..
                },
            ) => Self::copy_assign_fields(fields, source_fields)?,
            (
                StructFieldValue::StructArray { elements, .. },
                StructFieldValue::StructArray {
                    elements: source_elements,
                    ..
                },
            ) if elements.len() == source_elements.len() => {
                for (fields, source_fields) in elements.iter_mut().zip(source_elements) {
                    Self::copy_assign_fields(fields, source_fields)?;
                }
            }
            (
                StructFieldValue::Pointer { pointer, .. },
                StructFieldValue::Pointer {
                    pointer: source_pointer,
                    ..
                },
            ) => *pointer = source_pointer.clone(),
            _ => {
                return Err(CustError::new(
                    "internal aggregate assignment field layout mismatch",
                ));
            }
        }
        Ok(())
    }

    fn copy_assign_fields(
        fields: &mut HashMap<String, StructFieldValue>,
        source_fields: &HashMap<String, StructFieldValue>,
    ) -> CustResult<()> {
        if fields.len() != source_fields.len() {
            return Err(CustError::new(
                "internal aggregate assignment field layout mismatch",
            ));
        }
        for (name, field) in fields {
            let source = source_fields.get(name).ok_or_else(|| {
                CustError::new("internal aggregate assignment field layout mismatch")
            })?;
            field.copy_assign_from(source)?;
        }
        Ok(())
    }
}

